import{c as i,$ as o,Q as r,j as n,g as t,o as s,n as c,m as l}from"./chunks/framework.Ce_49mA8.js";const y=JSON.parse('{"title":"Calculator & Recipes","description":"Comprehensive guide to designing bill of materials specification sheets, calculating cost price, managing overhead expenses, and dispatching batches to the workbench in OmniCraft ERP.","frontmatter":{"title":"Calculator & Recipes","description":"Comprehensive guide to designing bill of materials specification sheets, calculating cost price, managing overhead expenses, and dispatching batches to the workbench in OmniCraft ERP.","datePublished":"2026-11-15","dateModified":"2026-11-19","order":6},"headers":[],"relativePath":"docs/spaces/production/calculator.md","filePath":"docs/spaces/production/calculator.md","lastUpdated":1795046400000}'),d={name:"docs/spaces/production/calculator.md"},u={id:"calculator-recipes-cost-pricing",tabindex:"-1"};function h(g,e,p,m,f,b){const a=o("DocIcon");return r(),n("div",null,[t("h1",u,[s(a,{name:"calculator"}),e[0]||(e[0]=c(" Calculator: Recipes & Cost Pricing ",-1)),e[1]||(e[1]=t("a",{class:"header-anchor",href:"#calculator-recipes-cost-pricing","aria-label":'Permalink to "Calculator: Recipes & Cost Pricing"'},"​",-1))]),e[2]||(e[2]=l('<p>In craftsmanship and small-scale manufacturing, the most dangerous financial trap is the illusion of high profitability calculated hastily &quot;in your head&quot; based solely on raw material costs. When an artisan fails to account for active labor time, machine wear, cutting waste, packaging components, and workshop fixed overheads, the enterprise silently drifts into a hidden cash flow deficit.</p><p>The <strong>&quot;Calculator&quot;</strong> tab in <strong>OmniCraft ERP</strong> serves as the central engineering and financial headquarters of your workshop. Here, you design digital bill of materials specification sheets, calculate objective cost prices factoring in both direct and indirect expenses, simulate batches of any volume, and schedule verified production orders onto the workbench with a single click.</p><div class="tip custom-block"><p class="custom-block-title">Helpful Guide for Single Custom Orders</p><p>Looking to quickly estimate a custom one-off order formula or download a pre-built spreadsheet template for your workshop? Check out our <a href="/calculators/product-cost-calculator">Universal Online Product Cost Calculator</a> or specialized editions for <a href="/calculators/leather-cost-calculator">leathercrafters</a> and <a href="/calculators/cake-cost-calculator">bakers &amp; confectioners</a>.</p></div><hr><h2 id="screen-architecture-two-operational-modes" tabindex="-1">Screen Architecture: Two Operational Modes <a class="header-anchor" href="#screen-architecture-two-operational-modes" aria-label="Permalink to &quot;Screen Architecture: Two Operational Modes&quot;">​</a></h2><p>The Calculator interface is split into two interconnected functional modes via the toggle switch at the top of the screen:</p><ol><li><strong>&quot;Batch Calculation&quot;</strong> — an operational production planning tool. Select an existing item from your catalog, specify the batch quantity, pick a packaging configuration, and immediately inspect a granular cost breakdown with the option to launch the batch directly into production.</li><li><strong>&quot;Recipe Database&quot;</strong> — a catalog manager and specification builder. Here, you construct new product templates, edit material consumption rates, configure overhead coefficients, configure web showcase listings, and manage discontinued recipes in the archive.</li></ol><hr><h2 id="designing-a-specification-sheet-recipe-builder" tabindex="-1">Designing a Specification Sheet (Recipe Builder) <a class="header-anchor" href="#designing-a-specification-sheet-recipe-builder" aria-label="Permalink to &quot;Designing a Specification Sheet (Recipe Builder)&quot;">​</a></h2><p>To construct a new bill of materials specification sheet, switch to the <strong>&quot;Recipe Database&quot;</strong> mode and click the <strong>&quot;Create Recipe&quot;</strong> button. The modal recipe builder dialog will open.</p><h3 id="_1-core-product-parameters" tabindex="-1">1. Core Product Parameters <a class="header-anchor" href="#_1-core-product-parameters" aria-label="Permalink to &quot;1. Core Product Parameters&quot;">​</a></h3><ul><li><strong>Product Name (Recipe):</strong> Full title of the model (for example, <em>“Classic Buffalo Leather Belt (Chocolate)”</em>).</li><li><strong>Link to stock product (optional):</strong> If a product inventory card already exists on the finished goods warehouse (the &quot;Showcase&quot; tab), you can link this recipe directly to it, or keep the default option — <em>“Create new product from scratch”</em>.</li><li><strong>“Product model”</strong> links recipes for variants of the same product. Pick a model from the list or click the pencil button to manage the product models directory (create, rename, and delete). When you complete production, the batch belongs to the product with that model.</li><li><strong>Labor Time (hrs):</strong> Standard bench time required by a skilled craftsman to assemble a single unit (for example, <code>1.5</code> hours). When calculating cost price, the system multiplies this bench time by the active hourly rate from Workspace Settings, adjusted by your custom craftsmanship complexity multiplier.</li></ul><hr><h2 id="three-tiered-recipe-structure" tabindex="-1">Three-Tiered Recipe Structure <a class="header-anchor" href="#three-tiered-recipe-structure" aria-label="Permalink to &quot;Three-Tiered Recipe Structure&quot;">​</a></h2><p>The recipe builder unifies manufacturing specifications, warehouse packaging, and online retail catalog listings across three dedicated tabs:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"></span><div><strong>&quot;Product Assembly&quot; Tab:</strong><br> Bill of materials deducted on the workbench during batch manufacturing. </div></li><li><span class="craft-list-bullet"></span><div><strong>&quot;Packaging Assembly&quot; Tab:</strong><br> Deferred packaging supplies deducted strictly at the point of sale. </div></li><li><span class="craft-list-bullet"></span><div><strong>&quot;Web Store&quot; Tab:</strong><br> Storefront item parameters, photography, and online catalog publication settings. </div></li></ul><h3 id="tab-1-product-assembly-manufacturing-bill-of-materials" tabindex="-1">Tab 1: &quot;Product Assembly&quot; (Manufacturing Bill of Materials) <a class="header-anchor" href="#tab-1-product-assembly-manufacturing-bill-of-materials" aria-label="Permalink to &quot;Tab 1: &quot;Product Assembly&quot; (Manufacturing Bill of Materials)&quot;">​</a></h3><p>This section defines the bill of materials physically consumed during assembly on the workbench. These items are deducted from the warehouse when a batch is completed.</p><ol><li><strong>Material Category:</strong> The dropdown filter allows you to instantly isolate inventory items (leather, timber, metal hardware, thread, adhesives).</li><li><strong>Warehouse Material:</strong> Select an active item from your actual warehouse inventory stock. The application displays the item title and standard unit of measurement.</li><li><strong>Consumption Rate:</strong> Enter the exact quantity required per single finished unit (<code>1.2</code> sq ft, <code>3.5</code> lin m, <code>4</code> pcs).</li><li>Click the <strong>&quot;Add&quot;</strong> button. The line item is recorded into the bill of materials.</li></ol><div class="tip custom-block"><p class="custom-block-title">Master Craftsman Tip: Factor in Cutting Waste</p><p>When working with natural full-grain leather, raw hardwood lumber, or metal sheets, perimeter off-cuts, sawdust, and natural grain defects are inevitable. Never specify a consumption rate matched strictly to finished component geometry. Always add a 10–20% cutting margin so your estimated cost price genuinely absorbs raw material scrap.</p></div><h3 id="tab-2-packaging-assembly-deferred-packaging-deduction" tabindex="-1">Tab 2: &quot;Packaging Assembly&quot; (Deferred Packaging Deduction) <a class="header-anchor" href="#tab-2-packaging-assembly-deferred-packaging-deduction" aria-label="Permalink to &quot;Tab 2: &quot;Packaging Assembly&quot; (Deferred Packaging Deduction)&quot;">​</a></h3><p>Packaging serves a dual purpose: it protects handcrafted goods during delivery and establishes a premium brand impression. However, packaging materials follow an entirely different inventory lifecycle.</p><ul><li>Select a packaging set from the dropdown menu: standard configurations (<em>&quot;Standard&quot;</em>, <em>&quot;Premium&quot;</em>) or custom packaging types created via the <strong>&quot;Manage Packaging Types&quot;</strong> dialog (e.g., <em>&quot;Engraved Wooden Box with Ribbon&quot;</em>).</li><li>Add packaging materials from active stock (cardboard mailer box, tissue paper, brand tag, seal wax) specifying consumption per unit.</li></ul><div class="info custom-block"><p class="custom-block-title">Inventory Physics: Why Packaging Is Not Deducted on the Workbench</p><p>A finished handcrafted item may sit in warehouse stock for weeks before a buyer orders it. If packaged immediately on the workbench, cardboard boxes risk collecting dust or sustaining shelf scuffs. Furthermore, a buyer may choose a basic cotton pouch or request an upgrade to an engraved gift box. Therefore, packaging components <strong>are not deducted during production on the workbench</strong>. They are estimated within the recipe for pricing purposes, but physically deducted from stock strictly when the sales receipt is finalized.</p></div><hr><h2 id="packaging-and-boxing-of-finished-goods" tabindex="-1">Packaging and Boxing of Finished Goods <a class="header-anchor" href="#packaging-and-boxing-of-finished-goods" aria-label="Permalink to &quot;Packaging and Boxing of Finished Goods&quot;">​</a></h2><p>Boxing finished craft items into branded packaging is the final stage of the manufacturing cycle, directly affecting delivery safety and workshop reputation. OmniCraft ERP features a flexible packaging management engine that links multiple packaging sets to a single recipe and incorporates packaging costs into total batch estimates.</p><h3 id="purpose-and-segregated-inventory-logic" tabindex="-1">Purpose and Segregated Inventory Logic <a class="header-anchor" href="#purpose-and-segregated-inventory-logic" aria-label="Permalink to &quot;Purpose and Segregated Inventory Logic&quot;">​</a></h3><p>Unlike production raw materials (leather, wood, metal, adhesive) consumed irrevocably on the workbench, packaging materials are consumed right before order handoff to a customer or courier. Segregated deduction addresses three practical workshop needs:</p><ol><li><strong>Packaging Protection:</strong> Finished goods rest in inventory safely stored in cloth protective bags without risking scuffs on gift boxes.</li><li><strong>Flexible Product Kits:</strong> Freedom to sell the exact same physical item in minimal craft wrap or in a luxury wooden gift case.</li><li><strong>Accurate Cost Price Accounting:</strong> Boxes, filler tissue, and wax seals are factored into planning estimates, but warehouse inventory is deducted strictly upon finalized sale.</li></ol><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><p>Before setting up packaging sets in the Calculator:</p><ul><li>Book packaging supplies into the warehouse via <strong>&quot;Batch Purchase&quot;</strong> under the &quot;Packaging&quot; category (boxes, tissue paper, satin ribbons, wax seals, brand tags);</li><li>Ensure each item specifies proper physical units of measurement (pcs, lin m, rolls).</li></ul><h3 id="step-by-step-procedure-for-packaging-types-and-recipe-linking" tabindex="-1">Step-by-Step Procedure for Packaging Types and Recipe Linking <a class="header-anchor" href="#step-by-step-procedure-for-packaging-types-and-recipe-linking" aria-label="Permalink to &quot;Step-by-Step Procedure for Packaging Types and Recipe Linking&quot;">​</a></h3><ol><li><strong>Open the Packaging Types Window:</strong> In the recipe editor, switch to the <strong>&quot;Packaging Assembly&quot;</strong> tab and click the gear icon button <strong>&quot;Manage Packaging Types&quot;</strong> next to the packaging dropdown selector.</li><li><strong>Create a New Packaging Type:</strong> In the <strong>&quot;Manage Packaging&quot;</strong> modal dialog, enter the format name into the <strong>&quot;Packaging Name&quot;</strong> field (e.g., <em>&quot;Engraved Wooden Box&quot;</em>, <em>&quot;Eco-Craft Mailer&quot;</em>) and click <strong>&quot;Add&quot;</strong>. The new type appears in the catalog list immediately.</li><li><strong>Soft-Delete Deprecated Formats:</strong> If a packaging format is retired, click the red trash icon beside its name. The packaging type is archived safely without disrupting historical orders. Click <strong>&quot;Close&quot;</strong> to return to the recipe editor.</li><li><strong>Assemble the Packaging Kit:</strong><ul><li>Select your created packaging format from the <strong>&quot;Packaging&quot;</strong> dropdown;</li><li>Filter the stock category in <strong>&quot;Category&quot;</strong> (e.g., <em>&quot;Packaging&quot;</em>);</li><li>Select the inventory item from <strong>&quot;Packaging Material&quot;</strong>;</li><li>Specify unit consumption in <strong>&quot;Quantity&quot;</strong>;</li><li>Click <strong>&quot;Add&quot;</strong>. The item appears in the packaging kit table with its current Moving Average Cost (MAC) calculated from active stock.</li></ul></li><li><strong>Estimate in Production Batches and Deduct on Sale:</strong> When planning a batch in <strong>&quot;Batch Calculation&quot;</strong> mode, choose your packaging set. The software incorporates packaging materials into batch expenditure. Upon sales confirmation in the Sales Log or Order Desk, the software automatically deducts the designated packaging components from warehouse stock.</li></ol><div class="tip custom-block"><p class="custom-block-title">Wholesale vs. Retail Packaging Variants</p><p>A single recipe can hold distinct packaging configurations. For example, a <em>&quot;Wholesale&quot;</em> kit holds only a poly sleeve and barcode label, whereas a <em>&quot;Gift Box&quot;</em> variant includes rigid cardboard, tissue paper, and a wax seal. When calculating batches, the craftsman switches kits seamlessly, instantly inspecting the exact variance in unit cost.</p></div><h3 id="tab-3-web-store-public-showcase-integration" tabindex="-1">Tab 3: &quot;Web Store&quot; (Public Showcase Integration) <a class="header-anchor" href="#tab-3-web-store-public-showcase-integration" aria-label="Permalink to &quot;Tab 3: &quot;Web Store&quot; (Public Showcase Integration)&quot;">​</a></h3><p>If you use the built-in online showcase module, your product listing can be configured directly inside the recipe constructor without opening separate administration menus:</p><ul><li><strong>Publish to Web Showcase:</strong> Master toggle controlling visibility in your public online store.</li><li><strong>Web URL Slug:</strong> Unique clean URL identifier for the product page (e.g., <code>leather-belt-classic-brown</code>).</li><li><strong>Showcase Badge:</strong> Visual highlight badge displayed on the product card (<em>&quot;Bestseller&quot;</em>, <em>&quot;Handstitched&quot;</em>, <em>&quot;Limited Edition&quot;</em>).</li><li><strong>Showcase Price:</strong> Specific retail price applied to orders placed via the web storefront.</li><li><strong>Showcase Description:</strong> Full text field with Markdown formatting support for listing specifications, dimensions, care instructions, and material origins.</li></ul><hr><h2 id="configuring-rates-markup-and-overhead-expenses" tabindex="-1">Configuring Rates, Markup, and Overhead Expenses <a class="header-anchor" href="#configuring-rates-markup-and-overhead-expenses" aria-label="Permalink to &quot;Configuring Rates, Markup, and Overhead Expenses&quot;">​</a></h2><p>Indirect workshop expenses — equipment depreciation, power utilities, shop rent, and consumables — are frequently neglected. The <strong>&quot;Configure Rate, Markup, and Overheads&quot;</strong> button expands a dedicated drawer for granular cost tuning:</p><h3 id="_1-labor-compensation-and-profit-margin" tabindex="-1">1. Labor Compensation and Profit Margin <a class="header-anchor" href="#_1-labor-compensation-and-profit-margin" aria-label="Permalink to &quot;1. Labor Compensation and Profit Margin&quot;">​</a></h3><ul><li><strong>Master Hourly Rate:</strong> Individual labor complexity multiplier. If the global workshop rate is <code>$20/hr</code> and the current item involves intricate hand tooling, apply a multiplier of <code>1.5</code> (effective rate becomes <code>$30/hr</code>). For basic cutting tasks, the multiplier can be adjusted to <code>0.8</code>.</li><li><strong>Cost Markup:</strong> Product-specific markup multiplier applied on top of the global workspace markup percentage, enabling tailored margins across diverse product tiers.</li></ul><h3 id="_2-percentage-overhead-expenses" tabindex="-1">2. Percentage Overhead Expenses <a class="header-anchor" href="#_2-percentage-overhead-expenses" aria-label="Permalink to &quot;2. Percentage Overhead Expenses&quot;">​</a></h3><p>The program retrieves standard overhead categories from Workspace Settings (machine depreciation, workshop lighting, cutting defect allowance, consumable hand tools). Each norm features an independent multiplier:</p><ul><li>For a product crafted entirely by hand with zero machinery, set the machinery depreciation multiplier to <code>0.0</code>.</li><li>For a complex item requiring hours of thermal curing or CNC milling, increase the machine wear and power utility multiplier to <code>1.5</code>–<code>2.0</code>.</li></ul><h3 id="_3-fixed-overhead-expenses-per-unit" tabindex="-1">3. Fixed Overhead Expenses per Unit <a class="header-anchor" href="#_3-fixed-overhead-expenses-per-unit" aria-label="Permalink to &quot;3. Fixed Overhead Expenses per Unit&quot;">​</a></h3><p>Direct fixed overhead charges applied as a flat currency amount to every single unit produced (batch inspection fee, external logistics transit, specialized serialized tags).</p><p>The program recalculates and displays the resulting percentage and flat overhead totals in real time.</p><hr><h2 id="cost-pricing-mathematical-model" tabindex="-1">Cost Pricing Mathematical Model <a class="header-anchor" href="#cost-pricing-mathematical-model" aria-label="Permalink to &quot;Cost Pricing Mathematical Model&quot;">​</a></h2><p>OmniCraft ERP calculates product economics using an objective formula combining direct raw materials, labor compensation, and tiered overheads:</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Product Calculation</span><div class="formula-heading">Total Planned Production Cost per Single Unit</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Unit Cost Price</span><span class="math-op">=</span><span class="math-var">Materials (MAC)</span><span class="math-op">+</span><span class="math-var">Master Labor</span><span class="math-op">+</span><span class="math-var">Overhead Expenses</span><span class="math-op">+</span><span class="math-var">Packaging</span></div></div></div><p>Where the formula terms are derived according to strict bookkeeping rules:</p><ol><li><strong>Product Raw Materials:</strong> Sum of consumption rates multiplied by each material&#39;s current moving average cost (MAC) in active warehouse stock at that second.</li><li><strong>Labor Compensation:</strong> Product labor hours multiplied by the base hourly rate and adjusted by the craftsmanship complexity multiplier.</li><li><strong>Overhead Expenses:</strong> Flat fixed overhead charges plus the percentage overhead applied to the sum of raw materials and labor: <code>Overheads = Fixed Overheads + (Materials + Labor) × (Total Overheads % / 100)</code>.</li><li><strong>Packaging Assembly:</strong> Cost of the selected packaging set based on current warehouse inventory MAC valuation.</li></ol><div class="info custom-block"><p class="custom-block-title">Automatic Warehouse Synchronization via Moving Average Cost (MAC)</p><p>You never need to manually recalculate specification sheets when vendor prices fluctuate. Whenever a new delivery of leather, hardware, or timber is booked at a higher price, the system automatically updates the moving average cost of that material. Every recipe referencing that item immediately reflects updated, accurate cost figures.</p></div><hr><h2 id="batch-calculation-dispatching-to-the-workbench" tabindex="-1">Batch Calculation &amp; Dispatching to the Workbench <a class="header-anchor" href="#batch-calculation-dispatching-to-the-workbench" aria-label="Permalink to &quot;Batch Calculation &amp; Dispatching to the Workbench&quot;">​</a></h2><p>Once your recipe catalog is established, switch to the <strong>&quot;Batch Calculation&quot;</strong> mode to estimate production runs before launching them into the shop.</p><ol><li><strong>Select Product:</strong> Click the <strong>&quot;Find product recipe...&quot;</strong> search container and select the target model from your active database.</li><li><strong>Specify Batch Volume:</strong> In the <strong>&quot;Quantity to produce&quot;</strong> field, input your scheduled batch run (e.g., <code>10</code> units).</li><li><strong>Choose Packaging:</strong> Select a packaging option from the dropdown or leave it set to <em>&quot;No packaging&quot;</em>.</li><li><strong>Review Cost Breakdown:</strong> The &quot;BATCH COST BREAKDOWN&quot; card provides a transparent financial summary: <ul><li>Product assembly materials;</li><li>Master labor compensation alongside total bench hours;</li><li>Overhead expenses (percentage and fixed);</li><li>Packaging assembly components;</li><li>Total planned batch cost alongside net unit cost.</li></ul></li><li><strong>Component Bill of Materials Table:</strong> Review the comprehensive batch schedule detailing material names, required quantities, purpose badges (blue — <strong>&quot;Product Assembly&quot;</strong>, purple — <strong>&quot;Packaging: Name&quot;</strong>), and net costs.</li></ol><div class="tip custom-block"><p class="custom-block-title">AI Cost Structure &amp; Margin Breakdown</p><p>Next to the cost details card header, click the button with the spark icon to trigger an AI analysis of the current batch. The AI assistant evaluates the ratio between material and labor costs, checks target profitability against market benchmarks, and suggests practical margin optimizations.</p></div><hr><h2 id="material-stock-verification-scheduling" tabindex="-1">Material Stock Verification &amp; Scheduling <a class="header-anchor" href="#material-stock-verification-scheduling" aria-label="Permalink to &quot;Material Stock Verification &amp; Scheduling&quot;">​</a></h2><p>Once you are satisfied with the figures, click the green <strong>&quot;Start Production&quot;</strong> button. The application instantly cross-references warehouse inventory:</p><ul><li><strong>Stock Is Sufficient:</strong> The batch is queued immediately on the <strong>&quot;Workbench&quot;</strong> tab under planned production status, reserving inventory materials while a confirmation toast appears.</li><li><strong>Stock Shortage Detected:</strong> The system opens an <strong>&quot;Insufficient Materials!&quot;</strong> warning modal.</li></ul><p>The dialog displays a detailed breakdown of lacking items, showing required quantities alongside current available stock:</p><div class="warning custom-block"><p class="custom-block-title">Missing Material Inventory</p><ul><li><strong>Buffalo Leather (Chocolate):</strong> required <code>12.0</code> sq ft, available in stock <code>4.5</code> sq ft;</li><li><strong>Waxed Thread 0.8mm:</strong> required <code>35.0</code> lin m, available in stock <code>10.0</code> lin m.</li></ul></div><p>The craftsman can choose between two actions:</p><ol><li><strong>&quot;Cancel&quot;:</strong> Abort scheduling until incoming material shipments are booked in the Warehouse tab.</li><li><strong>&quot;Yes, schedule&quot;:</strong> Force-schedule the batch onto the Workbench. The order appears in the workbench queue tagged in a waiting-for-procurement status, ensuring the task remains visible in your pipeline.</li></ol><hr><h2 id="catalog-management-unlinking-and-archiving" tabindex="-1">Catalog Management, Unlinking, and Archiving <a class="header-anchor" href="#catalog-management-unlinking-and-archiving" aria-label="Permalink to &quot;Catalog Management, Unlinking, and Archiving&quot;">​</a></h2><p>In <strong>&quot;Recipe Database&quot;</strong> mode, you can inspect your complete catalog of technological cards with built-in pagination (25 items per page). The table displays standard labor bench time, overhead percentages, and calculated unit cost prices.</p><h3 id="modifying-unlinking-and-archiving-recipes" tabindex="-1">Modifying, Unlinking, and Archiving Recipes <a class="header-anchor" href="#modifying-unlinking-and-archiving-recipes" aria-label="Permalink to &quot;Modifying, Unlinking, and Archiving Recipes&quot;">​</a></h3><p>Each active row provides immediate inline actions:</p><ul><li><strong>Edit (pencil icon):</strong> Opens the recipe builder to update consumption rates, bench time, or overhead multipliers. Changes apply to all new batch calculations immediately, but do not retroactively alter the valuation of previously finished goods.</li><li><strong>Delete Tech Card (link-off icon):</strong> Unlinks the recipe from its associated inventory product. When confirmed, the specification sheet is removed from the Calculator, but the physical product card and its finished stock remain intact in the warehouse. This is essential when discontinuing in-house production while continuing to sell remaining warehouse inventory.</li><li><strong>Archive (archive box icon):</strong> Moves the recipe to the archive. The model is hidden from the batch calculator search index, keeping your active workspace uncluttered.</li></ul><div class="warning custom-block"><p class="custom-block-title">Production Safety Lock: Archiving Blocked</p><p>OmniCraft ERP will programmatically block archiving if a batch of that product is currently active or planned on the Workbench. You must first finish the production run or cancel the pending order before the recipe can be safely archived.</p></div><h3 id="working-with-archived-recipes" tabindex="-1">Working with Archived Recipes <a class="header-anchor" href="#working-with-archived-recipes" aria-label="Permalink to &quot;Working with Archived Recipes&quot;">​</a></h3><p>Use the toggle in the upper right corner to switch to the <strong>&quot;Archived&quot;</strong> view:</p><ul><li><strong>Restore (restore arrow icon):</strong> Instantly reinstates the specification sheet back into the active database with all original material consumption norms and financial coefficients.</li><li><strong>Delete Forever (trash icon):</strong> Permanently removes the recipe from the database. This action is permitted strictly when physical warehouse stock of that product is zero. If units remain in stock, the system requires conducting an inventory write-off in the finished goods tab first.</li></ul><hr><h2 id="related-documentation-cross-links" tabindex="-1">Related Documentation &amp; Cross-Links <a class="header-anchor" href="#related-documentation-cross-links" aria-label="Permalink to &quot;Related Documentation &amp; Cross-Links&quot;">​</a></h2><ul><li><a href="/docs/spaces/production/cycle">Production Cycle</a> — end-to-end walkthrough from procurement to point of sale.</li><li><a href="/docs/spaces/production/workbench">Workshop Workbench</a> — tracking active runs, material write-offs, and batch completion.</li><li><a href="/docs/spaces/production/showcase">Finished Goods Showcase</a> — inventory batches, FIFO costing, and warehouse stock.</li><li><a href="/docs/resources/warehouse">Raw Materials &amp; Warehouse</a> — purchasing invoices, shipping cost distribution, and stock tracking.</li></ul>',83))])}const v=i(d,[["render",h]]);export{y as __pageData,v as default};
